    summary:
      'Всички живи тела се наричат организми и са изградени от клетки. Едноклетъчните организми са от една клетка, а многоклетъчните имат специализирани клетки за различни функции. Всяка клетка има клетъчна мембрана (с избирателна пропускливост), цитоплазма (воден разтвор с органели) и наследствено вещество. Прокариотните клетки (бактерии) нямат ядро и наследственото вещество е направо в цитоплазмата, докато при еукариотните клетки то е обвито с обвивка и образува ядро.\n\nРастенията имат самостойно (автотрофно) хранене чрез фотосинтеза — от вода, минерални вещества и въглероден диоксид с помощта на хлорофила и светлината образуват органични вещества и отделят кислород. Животните имат несамостойно (хетеротрофно) хранене — приемат готови органични вещества. Дишането освобождава енергия чрез приемане на кислород и отделяне на въглероден диоксид. Отделянето изхвърля непотребни продукти (при растенията през устицата, а при животните чрез бъбреци, нефридии или малпигиеви тръбички).\n\nПри растенията веществата се движат по проводяща система (дървесинни и ликови цеви), а реакциите на дразнители са бавни тропизми или бързи настии. При животните веществата се пренасят от затворена или отворена кръвоносна система, нервната система приема информация, а опорно-двигателната система със скелет (външен или вътрешен) осигурява движение. Размножаването е безполово или полово (чрез полови клетки и оплождане — външно или вътрешно). Индивидуалното развитие включва зародишно и следзародишно развитие, което при животните е пряко или непряко.',
