      'Царство Монера обединява най-малките едноклетъчни прокариотни (предядрени) организми — бактерии и цианобактерии. При тях няма ядро и наследственото вещество (пръстеновидна молекула ДНК) е разположено направо в цитоплазмата. Бактериалната клетка има клетъчна мембрана, здрава клетъчна стена (при някои и капсула), рибозоми в цитоплазмата, а често и камшичета за движение или пили за прикрепване.\n\nБактериите са автотрофни (фотосинтезиращи — без да отделят кислород, или хемосинтезиращи — окисляващи неорганични вещества) и хетеротрофни (паразити и сапробионти). Дишането им е аеробно (кислородно) или анаеробно (безкислородно). Размножават се безполово чрез делене на две, а при неблагоприятни условия някои образуват устойчива спора.\n\nЦианобактериите са около 10 пъти по-големи от бактериите. В цитоплазмата им има рибозоми и мембрани с хлорофил и други багрила, които им придават синьо-зелен цвят. Всички цианобактерии са автотрофни (фотосинтезират и отделят кислород), аеробни организми и се размножават чрез делене на две.',
