    title: '6-7. Царство Протиста. Тип Кореноножки, тип Камшичести и тип Ресничести',
    summary:
      'Царство Протиста обединява едноклетъчните еукариотни (същинскоядрени) организми — наследственото им вещество е в ядро. Според храненето се делят на автотрофни, хетеротрофни и миксотрофни (смесено хранене — на светло фотосинтезират, а на тъмно се хранят хетеротрофно). Свободно живеещите дишат аеробно, а паразитните са анаероби. Размножават се чрез делене на две.\n\nОсновен признак за класификацията на протистите са органелите за движение. Тип Кореноножки (напр. обикновена амеба) се движат и улавят храна чрез временни цитоплазмени образувания — псевдоподи (лъжливи крачка); имат съкратителна вакуола за изхвърляне на излишната вода, а при неблагоприятни условия образуват циста. Тип Камшичести (напр. зелена еуглена) се движат чрез едно или повече постоянни камшичета; зелената еуглена има хроматофори с хлорофил, очно петно за ориентиране към светлината и е типичен миксотроф.\n\nТип Ресничести (напр. чехълче) се движат чрез многобройни постоянни реснички. Чехълчето има постоянна форма, две ядра (голямо и малко), клетъчна уста и клетъчна глътка за хранене с бактерии, както и две съкратителни вакуоли в двата края на клетката, работещи последователно.',
