      'Едноклетъчните колониални организми са групи от различен брой еукариотни протисти (от 4 до хиляди), обединени в колония. Отделните клетки могат да бъдат свързани помежду си чрез безцветна желеподобна материя, тънки цитоплазмени мостчета или общо стъбълце с разклонения. Клетките в колонията са или еднакви, или различни по структура и функция.\n\nГониумът е колония с форма на пластинка от 4, 16 или 32 еднакви клетки в желеподобна материя. Всяка клетка има две камшичета и изпълнява всички жизнени функции, като при делене образува дъщерна колония. Волвоксът образува сферична колония от стотици до 20 000 клетки, свързани с цитоплазмени мостчета. При него има специализация: дребни вегетативни клетки с две камшичета за движение и хранене и едри размножителни клетки, които дават началото на дъщерни колонии.\n\nЗоотамниумът има форма на отворено чадърче с общо разклонено стъбълце, прикрепено към субстрата и изпълнено с обща цитоплазма. По-голямата част от клетките са дребни камбанковидни, а по-едрите кълбовидни клетки натрупват хранителни вещества, образуват реснички, откъсват се и дават началото на нова колония.',
