    summary:
      'Едноклетъчните организми (микроорганизми, микроби) изпълняват незаменима роля в природата. Сапробионтните бактерии са „санитари“ — те разграждат трупове на животни, растителни остатъци и отпадъци, като връщат минералните вещества в почвата и осигуряват многократното им използване.\n\nЧовекът използва полезни бактерии за пречистване на замърсени с нефт и органични отпадъци води, за производство на млечни продукти (сирене, кашкавал, кисело мляко чрез млечнокиселата бактерия), вино и лекарства. В червата на човека живее чревната бактерия, която подпомага храносмилането.\n\nСъщевременно има болестотворни (паразитни) едноклетъчни. Болестотворни бактерии причиняват туберкулоза (поразява белия дроб, предава се по въздушно-капков път), тетанус (поразява нервната система при нараняване на кожата) и трипер (предава се по полов път). Болестотворни протисти причиняват амебна дизентерия (през замърсени ръце, храна и вода), трихомониаза (по полов път и замърсени принадлежности) и токсоплазмоза (недостатъчно термично обработено месо, котки). Личната хигиена, чистата вода и термичната обработка на храната предпазват от заразяване.',
