      'За да наблюдаваме едноклетъчни организми под микроскоп, подготвяме временен препарат от капка застояла вода (от аквариум или ваза с цветя) върху чисто предметно стъкло. Поставяме 1–2 влакънца памук в капката, за да ограничим бързото движение на едноклетъчните, и я покриваме внимателно с покривно стъкло.\n\nТемпературата на водата силно влияе върху размножаването, храненето и дишането на едноклетъчните. В даденото изследване на водни слоеве с различна температура най-висока численост на едноклетъчни животни има при 25 °C (65%), при 22 °C са 20%, при 32 °C — 9%, при 20 °C — 5%, при 15 °C — 1%, а при 10 °C и 4 °C няма отчетена численост.\n\nПри изработване на модели на бактерия и чехълче трябва да се съобразим с реалното съотношение в размерите — представителите на царство Протиста (чехълче) многократно надвишават по размери представителите на царство Монера (бактерия). Различните клетъчни структури се представят с различни цветове и материали.',
