    summary:
      'При определяне на непознати едноклетъчни организми разглеждаме вида на клетката (прокариотна или еукариотна), органелите за движение, начина на живот (свободно живеещ или паразит) и начина на хранене. Стрептомицес е почвен прокариотен организъм (бактерия от царство Монера) без ядро; от него е получен антибиотикът стрептомицин за лечение на туберкулоза.\n\nОстаналите четири описани организма са еукариоти от царство Протиста и се хранят хетеротрофно. Костия (две камшичета, паразит по кожата на риби) и Трипанозома (камшиче, паразит в кръвта на човека, пренасян от мухата цеце и причиняващ сънна болест) принадлежат към тип Камшичести.\n\nБалантидиум (две ядра и многобройни реснички, паразит в червата на животни и човека) принадлежи към тип Ресничести. Пеломикса (много ядра и широки псевдоподи, свободно живеещ на тинесто дъно) принадлежи към тип Кореноножки.',
