    summary:
      'Преди повече от 3,5 млрд. години на Земята са се появили първите живи организми — древните прокариоти (първоначално хетеротрофи). По-късно се появяват цианобактериите, които отделят кислород в атмосферата и правят възможна появата на аеробните бактерии.\n\nСледващата стъпка в развитието на организмовия свят е появата на еукариотните едноклетъчни организми (царство Протиста). Предполага се, че колонии от едноклетъчни са възникнали при непълно разделяне на клетките след делене и по-късно са дали началото на многоклетъчните организми.\n\nДнес монерите и протистите населяват почти всички среди на Земята — полюсите, горещите извори, солените води на Мъртво море, океанските дълбини и пустините. Сред тях има автотрофи, хетеротрофи и миксотрофи, аероби и анаероби, както свободно живеещи форми, така и много паразити.',
